{
	"name": "@workspace/text",
	"version": "0.0.0",
	"private": true,
	"description": "Repository-private text normalization utilities.",
	"type": "module",
	"sideEffects": false,
	"exports": {
		".": "./src/index.ts"
	},
	"scripts": {
		"test": "vitest run",
		"typecheck": "tsc -p tsconfig.json"
	},
	"devDependencies": {
		"typescript": "catalog:tooling",
		"vitest": "catalog:testing"
	}
}

/** @description Owns private, deterministic display-text normalization. */

/** @description Normalizes whitespace and title-cases each whitespace-separated word. */
export function toDisplayName(value: string): string {
	return value
		.trim()
		.split(/\s+/u)
		.filter((word) => word.length > 0)
		.map((word) => `${word.charAt(0).toUpperCase()}${word.slice(1).toLowerCase()}`)
		.join(' ');
}
